import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.BZO4qERu.js";const h=JSON.parse('{"title":"動画生成プロバイダー","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/providers/video.md","filePath":"ja/integrations/providers/video.md","lastUpdated":1792323081000}'),r={name:"ja/integrations/providers/video.md"};function n(i,e,c,s,l,g){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="動画生成プロバイダー" tabindex="-1">動画生成プロバイダー <a class="header-anchor" href="#動画生成プロバイダー" aria-label="Permalink to &quot;動画生成プロバイダー&quot;">​</a></h1><p>Bot は <code>generate_video</code> ツールで動画を生成します。これを使うには、次の 2 つが両方とも必要です。</p><ol><li><strong>設定 → 統合 → 動画</strong> で、<strong>動画プロバイダー</strong>と動画モデルを少なくとも 1 つ設定する。</li><li><strong>Bot 設定 → マルチメディア</strong> で、Bot に<strong>動画生成モデル</strong>を 1 つ選ぶ。</li></ol><p>動画モデルが選ばれていない Bot には、そもそも <code>generate_video</code> ツール自体が提供されません。</p><hr><h2 id="サポートされるプロバイダー" tabindex="-1">サポートされるプロバイダー <a class="header-anchor" href="#サポートされるプロバイダー" aria-label="Permalink to &quot;サポートされるプロバイダー&quot;">​</a></h2><table tabindex="0"><thead><tr><th>プロバイダー</th><th>Client Type</th><th>デフォルト Base URL</th></tr></thead><tbody><tr><td><strong>OpenRouter</strong></td><td><code>openrouter-video</code></td><td><code>https://openrouter.ai/api</code></td></tr><tr><td><strong>ModelArk（BytePlus）</strong></td><td><code>modelark-video</code></td><td><code>https://ark.ap-southeast.bytepluses.com/api/v3</code></td></tr><tr><td><strong>Volcengine（Ark）</strong></td><td><code>volcengine-video</code></td><td><code>https://ark.cn-beijing.volces.com/api/v3</code></td></tr></tbody></table><p>いずれも <strong>API Key</strong> を入力するだけです。<strong>Base URL</strong> は未入力ならデフォルト値が使われます。</p><p>テンプレートには、現行の Seedance / Veo / Doubao Seedance のプリセットモデルが含まれています。</p><ul><li><strong>OpenRouter</strong>：<code>bytedance/seedance-2.0</code>、<code>google/veo-3.1-fast</code>、<code>google/veo-3.1-lite</code></li><li><strong>ModelArk</strong>：<code>dreamina-seedance-2-0-260128</code>、<code>dreamina-seedance-2-0-fast-260128</code>、<code>dreamina-seedance-2-5</code></li><li><strong>Volcengine</strong>：<code>doubao-seedance-2-0-260128</code>、<code>doubao-seedance-2-0-fast-260128</code>、<code>doubao-seedance-2-5</code></li></ul><p>OpenRouter は <strong>Import Models</strong> でオンラインのモデル一覧を取得できます。ModelArk と Volcengine にはオンライン一覧がないため、モデルはテンプレート由来か手動追加になります。</p><hr><h2 id="設定手順" tabindex="-1">設定手順 <a class="header-anchor" href="#設定手順" aria-label="Permalink to &quot;設定手順&quot;">​</a></h2><ol><li><strong>設定 → 統合 → 動画</strong> を開きます。</li><li>テンプレート一覧からプロバイダーを追加します（OpenRouter / ModelArk / Volcengine）。</li><li>API Key を入力します。デフォルト以外のエンドポイントを使う場合のみ Base URL を変更し、保存します。</li><li><strong>Video Models</strong> セクションを確認します。一覧が空なら、プロバイダーからインポートするか手動で 1 つ追加します。</li><li>Bot の <strong>設定 → マルチメディア</strong> で、<strong>動画生成モデル</strong>を選択します。</li></ol><hr><h2 id="bot-での使い方" tabindex="-1">Bot での使い方 <a class="header-anchor" href="#bot-での使い方" aria-label="Permalink to &quot;Bot での使い方&quot;">​</a></h2><p>Bot に「◯◯の動画を作って」と普通に話しかけるだけで使えます。裏側では次のことが起きています。</p><ul><li><code>generate_video</code> は<strong>バックグラウンドタスク</strong>で、すぐに task ID を返します。生成には通常数分かかり、Bot はバックグラウンドタスク用のツールで自分で進捗を追います。</li><li>パラメーターは <code>prompt</code> のほか、任意の <code>duration_seconds</code>、<code>resolution</code>（<code>720p</code>/<code>1080p</code>）、<code>aspect_ratio</code>（<code>16:9</code>、<code>9:16</code>、<code>1:1</code>）、プロバイダー固有の <code>size</code>、<code>generate_audio</code> があります。</li><li>完成した動画は、Bot のワークスペースの <code>/data/generated-videos/&lt;task_id&gt;.mp4</code> にダウンロードされます（プロバイダーの出力によっては <code>.webm</code>/<code>.mov</code> の場合もあります）。</li><li>動画が<strong>自動でどこかに送信されることはありません</strong>——Bot がメッセージの添付ファイルとして届けます。ワークスペースの <strong>ファイル</strong> タブから取得することもできます。</li></ul><p>生成完了の時点でワークスペースに到達できない場合でも、タスクは完了扱いになります。warning とプロバイダー側の出力 URL が付きますが、ディスクには保存されません。</p><hr><h2 id="関連ページ" tabindex="-1">関連ページ <a class="header-anchor" href="#関連ページ" aria-label="Permalink to &quot;関連ページ&quot;">​</a></h2><ul><li><a href="./llm.html">モデルプロバイダーとモデル</a></li><li><a href="./../../guides/container.html">ワークスペース</a></li></ul>',22)])])}const u=o(r,[["render",n]]);export{h as __pageData,u as default};
